-- 100: Kid Flash Cosmic Coaster at Six Flags Fiesta Texas (Carter, 2026-10-31,
-- with the RCDB page: "fiesta texas had a kid flash too"). Skyline P'Sghetti
-- Bowl, twin tracks - Left (Model F) 591.8 ft, Right (Model E) 566.5 ft, both
-- 24.5 ft, 0 inversions. Operated 4 Nov 2023 to Jul 2024, then SBNO to Jun 2026
-- and removed: closed Jul 2024. Two rows, as Over Georgia's two tracks are.
-- Safe to run twice.
INSERT INTO coasters (id, name, park, type, manu, model, h, s, l, inv, dur, yr, opened, openedPrec, closed, closedPrec, laps) SELECT (SELECT COALESCE(MAX(id),0)+1 FROM coasters), 'Kid Flash Cosmic Coaster (Left)', 'Six Flags Fiesta Texas', 'Steel', 'Skyline Attractions', 'Skyline P''Sghetti Bowl', 24.5, NULL, 591.8, 0, NULL, 2023, '2023-11-04', 'day', '2024-07', 'month', 1 WHERE NOT EXISTS (SELECT 1 FROM coasters WHERE name = 'Kid Flash Cosmic Coaster (Left)' AND park = 'Six Flags Fiesta Texas');
INSERT INTO activity (at, actor, kind, subject, n, detail) SELECT strftime('%Y-%m-%dT%H:%M:%fZ','now'), NULL, 'coaster_added', c.name, NULL, json_object('id', c.id, 'park', c.park) FROM coasters c WHERE c.name = 'Kid Flash Cosmic Coaster (Left)' AND c.park = 'Six Flags Fiesta Texas' AND NOT EXISTS (SELECT 1 FROM activity a WHERE a.kind = 'coaster_added' AND json_extract(a.detail, '$.id') = c.id);
INSERT INTO coasters (id, name, park, type, manu, model, h, s, l, inv, dur, yr, opened, openedPrec, closed, closedPrec, laps) SELECT (SELECT COALESCE(MAX(id),0)+1 FROM coasters), 'Kid Flash Cosmic Coaster (Right)', 'Six Flags Fiesta Texas', 'Steel', 'Skyline Attractions', 'Skyline P''Sghetti Bowl', 24.5, NULL, 566.5, 0, NULL, 2023, '2023-11-04', 'day', '2024-07', 'month', 1 WHERE NOT EXISTS (SELECT 1 FROM coasters WHERE name = 'Kid Flash Cosmic Coaster (Right)' AND park = 'Six Flags Fiesta Texas');
INSERT INTO activity (at, actor, kind, subject, n, detail) SELECT strftime('%Y-%m-%dT%H:%M:%fZ','now'), NULL, 'coaster_added', c.name, NULL, json_object('id', c.id, 'park', c.park) FROM coasters c WHERE c.name = 'Kid Flash Cosmic Coaster (Right)' AND c.park = 'Six Flags Fiesta Texas' AND NOT EXISTS (SELECT 1 FROM activity a WHERE a.kind = 'coaster_added' AND json_extract(a.detail, '$.id') = c.id);
